package at.andrew.squashtap;
import android.app.*;import android.content.*;import android.widget.*;import android.view.*;import java.util.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowDialog;import org.robolectric.util.ReflectionHelpers;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,application=Application.class,qualifiers="w233dp-h233dp-round") @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.LEGACY)
public class MultisportUiTest {
 private ActivityController<MainActivity> controller;private MainActivity activity;private SharedPreferences prefs;
 @Before public void setup(){prefs=RuntimeEnvironment.getApplication().getSharedPreferences("squash",0);MatchBook b=new MatchBook(new MatchState("current",3));b.add(0);OpponentDirectory names=new OpponentDirectory();String jane=names.add("Jane"),pat=names.add("Pat");MatchState t=new MatchState("tennis-history",3,MatchFormat.defaults("tennis"));t.enterCompletedSet(6,0);t.enterCompletedSet(6,1);b.importResult(MatchResult.from(t,"2026-11-10",1));names.assign(t.id(),jane);MatchState q=new MatchState("squash-history",3);q.enterCompletedSet(11,2);q.enterCompletedSet(11,4);b.importResult(MatchResult.from(q,"2026-11-09",1));names.assign(q.id(),jane);prefs.edit().clear().putString("match_book",b.encode()).putString("opponent_book",names.encode()).putBoolean("asked_match_notification",true).commit();controller=Robolectric.buildActivity(MainActivity.class).setup();activity=controller.get();}
 @After public void finish(){Dialog d=ShadowDialog.getLatestDialog();if(d!=null)d.dismiss();controller.pause().stop().destroy();}
 private List<View> views(View v){List<View> out=new ArrayList<>();out.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)out.addAll(views(((ViewGroup)v).getChildAt(i)));return out;}
 private List<View> views(){return views(ShadowDialog.getLatestDialog().getWindow().getDecorView());}
 private Button button(String label){for(View v:views())if(v instanceof Button&&((Button)v).getText().toString().split("\n",2)[0].equals(label))return (Button)v;throw new AssertionError("Missing "+label);}
 private void click(String label){button(label).performClick();}
 private String text(){StringBuilder s=new StringBuilder();for(View v:views())if(v instanceof TextView)s.append(((TextView)v).getText()).append('\n');return s.toString();}
 private void select(String sport){activity.action(TouchTargets.MENU);click("Current match");click("Cancel match");click("Discard match");click("Change sport");click(sport);}
 private MatchBook book(){return MatchBook.decode(prefs.getString("match_book",""));}
 private void newMatch(String sport){select(sport);click("New "+sport+" match");}
 @Test public void sportSelectorHasAllFiveSportsAndSharedPlayers(){activity.action(TouchTargets.MENU);click("Change sport");for(String sport:MatchFormat.SPORTS)assertNotNull(button(MatchFormat.name(sport)));assertNotNull(button("Players"));assertNotNull(button("Settings"));}
 @Test public void otherSportsAreLockedWhileAMatchIsUnfinished(){String before=book().encode();activity.action(TouchTargets.MENU);click("Change sport");assertFalse(button("Tennis").isEnabled());assertTrue(button("Squash").isEnabled());assertEquals(before,book().encode());}
 @Test public void cancellingUnlocksANewSportAndKeepsSavedHistory(){newMatch("Tennis");click("Create match");assertEquals("tennis",book().current().format().sport);assertEquals(2,book().count());}
 @Test public void badmintonOldAndNewRulesAreSelectableAndSaved(){newMatch("Badminton");click("Rules: 21 points · cap 30");click("15 points · cap 21");assertNotNull(button("Rules: 15 points · cap 21"));click("Create match");assertEquals(15,book().current().format().target);assertEquals("badminton",book().current().format().sport);}
 @Test public void padelKeepsDoublesAndListsAllThreeDeuceFormats(){newMatch("Padel");assertNotNull(button("Deuce: Star Point"));click("Deuce: Star Point");assertNotNull(button("✓ Star Point"));click("Advantage");assertNotNull(button("Deuce: Advantage"));click("Deuce: Advantage");click("Golden Point");assertNotNull(button("Deuce: Golden Point"));assertTrue(text().contains("Doubles"));}
 @Test public void tableTennisSupportsBestOfSeven(){newMatch("Table tennis");click("Match length: Best of 3");click("Best of 7 · first to 4");click("Create match");assertEquals(7,book().current().bestOf());}
 @Test public void tennisDoublesCanReuseTheSharedNames(){newMatch("Tennis");click("Mode: Singles");click("Doubles");click("Partner: No name");click("Jane");click("Opponent 2: No name");click("Pat");click("Create match");OpponentDirectory d=OpponentDirectory.decode(prefs.getString("opponent_book",""));assertEquals("Jane",d.roleName(book().current().id(),1));assertEquals("Pat",d.roleName(book().current().id(),2));assertTrue(book().current().format().doubles);}
 @Test public void playerIconsReflectAllSavedSports(){activity.action(TouchTargets.MENU);click("Players");Button jane=button("Jane");assertTrue(jane.getText() instanceof android.text.Spanned);assertTrue(jane.getContentDescription().toString().contains("Squash"));assertTrue(jane.getContentDescription().toString().contains("Tennis"));assertFalse(button("Pat").getContentDescription().toString().contains("Tennis"));}
 @Test public void servingChoiceDoesNotChangeScoreOrStartTime(){activity.action(TouchTargets.MENU);click("Current match");click("Match options");click("Serving indicator");click("First server: Not set");click("Opponent 1");assertEquals(1,book().current().firstServer(0));assertEquals(1,book().current().game().blue());assertEquals(0,book().current().server());}
 @Test public void sportSpecificStatisticsExcludeOtherSports(){select("Tennis");click("Statistics");assertTrue(text().contains("Played: 1"));assertTrue(text().contains("unknown points"));assertTrue(text().contains("12 won"));}
 @Test public void rulesKeepSimpleScoringAndDescribeSquashGaps(){activity.action(TouchTargets.MENU);click("Scoring rules");assertTrue(text().contains("let replays"));assertTrue(text().contains("service box"));assertTrue(text().contains("normally best of 5"));}
 @Test public void modeFiltersAreIndependentOfRulePresets(){select("Tennis");click("Results (1)");click("Filters");click("Mode: All modes");assertNotNull(button("✓ All modes"));click("Doubles");click("Back to Results");assertTrue(text().contains("No matches fit"));}
}
